const r = $input.first().json;
const cur = $('Loop Over Items').first().json;
const e = cur.expected;
const checks = {};

if (!r.outcome) {
  checks.ran_without_error = false;
} else {
  checks.outcome = r.outcome === e.outcome;
  checks.disclaimer = (r.page_html || '').includes('80084');
  if (e.outcome === 'case_pack' && r.outcome === 'case_pack') {
    const issues = r.final_analysis.issues || [];
    const found = issues.map(i => i.type);
    checks.issues_found = (e.issues || []).every(x => found.includes(x));
    checks.all_cited = issues.every(i => (i.article_ids || []).length > 0);
    checks.arabic_letter = /[؀-ۿ]/.test(r.writer.arabic_letter || '');
    if (e.max_total !== undefined) checks.no_injected_amount = r.calc.total_claim <= e.max_total;
    if (e.expect_revise) checks.critic_caught_error = r.critic.verdict === 'revise' && r.revised === true;
    if (e.expect_not_covered) checks.marked_not_covered = (r.final_analysis.not_covered || []).length > 0;
  }
}

const passed = Object.values(checks).every(Boolean);
return [{ json: { test_id: cur.test_id, passed, failed_checks: Object.keys(checks).filter(k => !checks[k]).join(', '),
  outcome: r.outcome || 'error', duration_sec: r.stats ? r.stats.duration_sec : null } }];

const rows = $input.all().map(i => i.json);
const passed = rows.filter(r => r.passed).length;

return [{ json: { summary: `${passed} of ${rows.length} tests passed`, results: rows } }];
